'use strict';
(() => {
  const {types,questions,axes,calculate}=window.GameData;
  const $=s=>document.querySelector(s);
  const storageKey='gamebti-save-v1';
  let answers=[],current=0,currentResult=null,screen='home',collectionFilter='all';
  let storageAvailable=true,toastTimer;
  const spriteURL='assets/whale-girls.png';
  const whaleMark='<img class="whale-mark" src="assets/whale-mark.svg" width="24" height="18" alt="">';
  function character(code,extraClass='card-icon'){
    const index=Object.keys(types).indexOf(code);
    return `<svg class="whale-sprite ${extraClass}" viewBox="${index%4} ${Math.floor(index/4)} 1 1" aria-hidden="true"><image href="${spriteURL}" width="4" height="4" preserveAspectRatio="none"/></svg>`;
  }
  $('#whale-cast').innerHTML=character('INTJ','whale-companion whale-left')+character('ENFP','whale-main')+character('INFP','whale-companion whale-right');
  function card(code,number){const t=types[code];return `<button class="player-card card-${t.group}" data-type="${code}" aria-label="了解${code} ${t.name}"><div class="card-top"><span class="card-code">${code}</span><span class="card-number">NO.${String(number).padStart(2,'0')}</span></div><div class="card-body"><div><h3>${t.name}</h3><span class="card-sub">${t.en}</span></div>${character(code)}</div><p class="card-quote">“${t.quote}”</p><span class="card-arrow">↗</span></button>`;}
  $('#featured-players').innerHTML=['INTJ','ENFP','ISTJ','ISFP'].map((c,i)=>card(c,[1,8,9,14][i])).join('');
  function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
  function readSave(){try{const value=JSON.parse(localStorage.getItem(storageKey));if(!value||value.version!==1||!Array.isArray(value.answers)||value.answers.length!==16||!Number.isInteger(value.current)||value.current<0||value.current>15||value.answers.some(a=>a!==null&&(!Number.isInteger(a)||a<0||a>3)))return null;return value;}catch{return null;}}
  function save(){try{localStorage.setItem(storageKey,JSON.stringify({version:1,answers,current,complete:!!currentResult}));}catch{if(storageAvailable){storageAvailable=false;notify('当前浏览器没能保存进度，这次测试仍可正常完成。');}}}
  function updateResume(){const saved=readSave();$('#resume-button').hidden=!saved;$('#resume-button').textContent=saved?.complete?'已经测过了？看看我的结果 →':`上次玩到第 ${(saved?.current??0)+1} 题，接着来 →`;}
  function showScreen(next){screen=next;['home','quiz','result'].forEach(id=>$('#'+id).hidden=id!==next);window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});if(next==='home')updateResume();}
  function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
  function start(){closeDialogs();answers=Array(16).fill(null);current=0;currentResult=null;save();renderQuiz();showScreen('quiz');}
  function renderQuiz(){const q=questions[current];$('#quiz').innerHTML=`<div class="quiz-toolbar"><button class="back-link" data-action="home">← 先回大厅</button><span class="mono">LEVEL ${String(current+1).padStart(2,'0')} <span style="color:#bdc0b2">/ 16</span></span></div><div class="progress-track" role="progressbar" aria-label="测试进度" aria-valuemin="0" aria-valuemax="16" aria-valuenow="${current+1}"><div class="progress-fill" style="width:${(current+1)/16*100}%"></div></div><div class="question-content"><span class="question-scene">${q.scene}</span><h2 class="question-title" id="question-title">${q.title}</h2><p class="question-subtitle">${q.sub}</p><div class="answers" role="group" aria-labelledby="question-title">${q.options.map((o,i)=>`<button class="answer ${answers[current]===i?'selected':''}" data-answer="${i}" aria-pressed="${answers[current]===i}"><span class="answer-key">${'ABCD'[i]}</span><span>${o}</span></button>`).join('')}</div><div class="quiz-bottom"><button class="quiz-prev" data-action="previous" ${current===0?'disabled':''}>← 上一题</button><span class="quiz-tip">凭直觉选就好，你平时的样子最有意思。</span><button class="button button-dark quiz-next" data-action="next" ${answers[current]===null?'disabled':''}>${current===15?'领取我的人格卡':'下一题'} <span>→</span></button></div></div>`;}
  function next(){if(answers[current]===null)return;if(current===15){currentResult=calculate(answers);save();renderResult();showScreen('result');return;}current++;save();renderQuiz();$('.question-title').setAttribute('tabindex','-1');$('.question-title').focus({preventScroll:true});}
  function renderResult(){const r=currentResult,t=types[r.code],mate=types[t.mate];$('#result').innerHTML=`<div class="result-heading"><span class="section-kicker mono">PLAYER IDENTITY UNLOCKED</span><h2>你的玩家人格，<span class="red">已解锁。</span></h2><p>这张卡，送给游戏里那个最自在的你。</p></div><div class="result-layout"><div class="identity-card card-${t.group}" id="identity-card"><div class="identity-top"><b class="identity-brand">gamebti ${whaleMark}</b><span class="mono">PLAYER ID CARD</span></div><div class="identity-code">${r.code}</div><h3>${t.name}</h3><span class="identity-en mono">${t.en}</span>${character(r.code,'identity-character')}<p class="identity-quote">“${t.quote}”</p><div class="identity-tags">${t.tags.map(tag=>`<span># ${tag}</span>`).join('')}</div><div class="identity-foot"><span>认真玩游戏，随便做自己。</span><span class="mono">VOL. 001</span></div></div><div class="result-detail"><h3>关于你，可能有点准。</h3><p class="result-intro">${t.intro}</p><div class="dimensions">${axes.map((axis,i)=>`<div class="dimension-row"><div class="dimension-labels"><span class="${r.percentages[i]>=50?'dominant':''}">${axis.left} ${r.percentages[i]}%</span><span class="${r.percentages[i]<=50?'dominant':''}">${100-r.percentages[i]}% ${axis.right}</span></div><div class="dimension-bar" role="img" aria-label="${axis.left} ${r.percentages[i]}%，${axis.right} ${100-r.percentages[i]}%"><span style="width:${r.percentages[i]}%"></span></div></div>`).join('')}</div><p class="dimension-note">百分比来自本次选项权重，表示两端的相对倾向，不是能力评分。50/50 时参考该维度第一题，轻松看就好。</p><div class="result-habits"><h3>这些小习惯，你中了几个？</h3><ul>${t.habits.map(h=>`<li>${h}</li>`).join('')}</ul></div><div class="result-mate">试试和 <b>${t.mate} · ${mate.name}</b> 组队<br>${t.mateText}</div></div></div><div class="result-actions"><button class="button button-dark" data-action="download">保存人格卡 <span>↓</span></button><button class="button button-outline" data-action="share">分享我的结果 ↗</button><button class="button button-outline" data-action="start">再测一次 ↻</button><button class="text-link" data-action="collection">看看其他玩家 →</button></div><p class="result-footnote">今天是这一型，明天也可以换个玩法。GameBTI 仅供娱乐，不是心理测评。</p>`;}
  function renderCollection(){const entries=Object.entries(types).filter(([,t])=>collectionFilter==='all'||t.group===collectionFilter);$('#collection-grid').innerHTML=entries.map(([code])=>card(code,Object.keys(types).indexOf(code)+1)).join('');$('#collection-filters').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.filter===collectionFilter));}
  function openCollection(code){closeDialogs();collectionFilter='all';renderCollection();$('#collection-dialog').showModal();if(code)previewType(code);}
  function previewType(code){const t=types[code];$('#collection-grid .type-preview-detail')?.remove();$('#collection-grid').querySelectorAll('.player-card').forEach(c=>c.classList.toggle('selected',c.dataset.type===code));const item=document.createElement('div');item.className='type-preview-detail';item.innerHTML=`<h3>${code} · ${t.name}</h3><p>${t.intro}</p><p>${t.tags.map(tag=>'#'+tag).join('　')}</p><button class="text-link" data-action="start">来测测，我是不是这一型 →</button>`;const selected=$(`#collection-grid [data-type="${code}"]`);const visibleCards=[...$('#collection-grid').querySelectorAll('.player-card')];const columns=Math.max(1,Math.round($('#collection-grid').clientWidth/(selected.offsetWidth+10)));const index=visibleCards.indexOf(selected);const end=Math.min(Math.floor(index/columns)*columns+columns-1,visibleCards.length-1);visibleCards[end].after(item);item.scrollIntoView({behavior:'smooth',block:'nearest'});}
  async function share(){const t=types[currentResult.code];const message=`我是 ${currentResult.code}「${t.name}」：${t.quote} 来 GameBTI 测测你的玩家人格。`;try{if(navigator.share&&location.protocol==='https:'){await navigator.share({title:'我的 GameBTI 玩家人格',text:message,url:location.href.split('#')[0]});return;}if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(`${message}\n${location.href.split('#')[0]}`);notify('结果和链接已复制，发给你的开黑搭子吧。');}else{showCopyDialog(`${message}\n${location.href.split('#')[0]}`);}}catch(e){if(e.name!=='AbortError')showCopyDialog(`${message}\n${location.href.split('#')[0]}`);}}
  function showCopyDialog(text){let d=$('#share-dialog');if(!d){d=document.createElement('dialog');d.id='share-dialog';d.className='about-dialog';document.body.append(d);}d.innerHTML='<button class="close-button" data-action="close" aria-label="关闭分享">×</button><h2>分享给你的搭子</h2><p>长按或选中文字，复制后发给朋友。</p><textarea aria-label="分享内容" readonly style="width:100%;min-height:150px;border:1px solid #d0d3c3;background:#fffdf5;border-radius:4px;padding:12px;font:inherit;font-size:13px;line-height:1.8"></textarea><p>站点默认为私人访问；朋友打开链接需要相应访问权限。</p>';d.querySelector('textarea').value=text;d.showModal();d.querySelector('textarea').select();}
  async function download(){const {code}=currentResult,t=types[code];const button=$('[data-action="download"]');button.disabled=true;button.textContent='正在生成…';try{if(document.fonts?.ready)await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1260;const c=canvas.getContext('2d');const backgrounds={analyst:'#ded8eb',diplomat:'#dce4cd',sentinel:'#f1e4b9',explorer:'#dce9ee'};c.fillStyle=backgrounds[t.group];c.fillRect(0,0,900,1260);c.fillStyle='#292d26';c.textAlign='left';c.font='bold 35px Arial';c.fillText('gamebti',65,90);const mark=new Image();mark.src='assets/whale-mark.svg';await mark.decode();c.drawImage(mark,213,59,43,34);c.textAlign='right';c.font='18px monospace';c.fillText('PLAYER ID CARD',835,86);c.strokeStyle='#292d2630';c.beginPath();c.moveTo(65,120);c.lineTo(835,120);c.stroke();c.textAlign='center';c.font='bold 125px Arial';c.fillText(code,450,293);c.font='bold 55px "Microsoft YaHei", sans-serif';c.fillText(t.name,450,380);c.font='18px monospace';c.fillText(t.en,450,427);const sprite=new Image();sprite.src=spriteURL;await sprite.decode();const spriteIndex=Object.keys(types).indexOf(code);const cellWidth=sprite.naturalWidth/4,cellHeight=sprite.naturalHeight/4;c.imageSmoothingEnabled=false;c.drawImage(sprite,spriteIndex%4*cellWidth,Math.floor(spriteIndex/4)*cellHeight,cellWidth,cellHeight,230,445,440,440);c.font='28px "Microsoft YaHei", sans-serif';c.fillText(`“${t.quote}”`,450,905);c.font='20px "Microsoft YaHei", sans-serif';c.fillStyle='#636c59';c.fillText(t.tags.map(tag=>'#'+tag).join('    '),450,976);c.fillStyle='#292d26';c.font='23px "Microsoft YaHei", sans-serif';c.fillText('认真玩游戏，随便做自己。',450,1080);c.font='16px "Microsoft YaHei", sans-serif';c.fillStyle='#6f7764';c.fillText('GameBTI · 趣味玩家人格测试 · 仅供娱乐',450,1131);c.font='16px monospace';c.fillText('JUST PLAY YOUR WAY.',450,1180);const output=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('empty')),'image/png'));const url=URL.createObjectURL(output);const a=document.createElement('a');a.href=url;a.download=`GameBTI-${code}-${t.name}.png`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('人格卡已生成，看看浏览器的下载列表。');}catch{notify('图片生成没成功，可以先用“分享我的结果”保存文字。');}finally{button.disabled=false;button.innerHTML='保存人格卡 <span>↓</span>';}}
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.answer!==undefined){answers[current]=Number(b.dataset.answer);save();document.querySelectorAll('.answer').forEach(a=>{const selected=Number(a.dataset.answer)===answers[current];a.classList.toggle('selected',selected);a.setAttribute('aria-pressed',String(selected));});$('.quiz-next').disabled=false;return;}if(b.dataset.filter){collectionFilter=b.dataset.filter;renderCollection();return;}if(b.dataset.type){if(!$('#collection-dialog').open)openCollection(b.dataset.type);else previewType(b.dataset.type);return;}switch(b.dataset.action){case 'start':start();break;case 'collection':openCollection();break;case 'about':$('#about-dialog').showModal();break;case 'close':b.closest('dialog').close();break;case 'home':showScreen('home');break;case 'next':next();break;case 'previous':if(current>0){current--;save();renderQuiz();}break;case 'download':download();break;case 'share':share();break;}});
  document.querySelectorAll('.brand,.footer-brand').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showScreen('home');}));
  $('#resume-button').addEventListener('click',()=>{const saved=readSave();if(!saved){updateResume();return;}answers=saved.answers;current=saved.current;if(saved.complete&&answers.every(a=>a!==null)){currentResult=calculate(answers);renderResult();showScreen('result');}else{currentResult=null;renderQuiz();showScreen('quiz');}});
  document.addEventListener('keydown',e=>{if(screen!=='quiz'||document.querySelector('dialog[open]')||e.altKey||e.ctrlKey||e.metaKey||e.repeat)return;const index='abcd'.indexOf(e.key.toLowerCase());if(index>=0&&e.key.length===1){document.querySelector(`[data-answer="${index}"]`)?.click();}if(e.key==='Enter'&&document.activeElement?.tagName!=='BUTTON'){e.preventDefault();next();}});
  document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const box=d.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)d.close();}}));
  updateResume();
})();
